// ---------------------------------------------------------------------------
// v27 - move the app off cleartext HTTP
//
// Until now every request - the OTP code, the JWT, the signup form, the
// Razorpay verification - travelled as plain text over http://13.200.97.252,
// readable and modifiable by anyone on the same network.
//
// This was held back because the socket connection had never been checked on
// 443. It has now been verified against the live server:
//   - GET https://api.cryptogram.tech/health         -> 200, db connected
//   - socket.io handshake over 443                   -> 200, upgrades:["websocket"]
//   - wss://api.cryptogram.tech/socket.io            -> upgrade accepted, OPEN
//   - uptimeSeconds on the https host and on the IP advanced in lockstep,
//     so both names front the same process - this is a drop-in change.
// ---------------------------------------------------------------------------

{
  const BASE = "src/apis/base_url.ts";
  let b = readMust(BASE);
  b = replaceOnce(b,
    [
      "// Production backend — AWS EC2 ap-south-1 (amigo-ghost, nginx port 80 → node 9090)",
      "// Elastic IP — permanent, never changes",
      "export const BACKEND_ORIGIN = 'http://13.200.97.252';",
    ].join("\n"),
    [
      "// Production backend - AWS EC2 ap-south-1 (amigo-ghost), reached over TLS.",
      "// Same server as the old http://13.200.97.252, just the encrypted front door:",
      "// health, the REST API and the socket.io websocket upgrade were all verified",
      "// on 443 before this was switched.",
      "export const BACKEND_ORIGIN = 'https://api.cryptogram.tech';",
      "// Previous cleartext origin, kept for reference only - do not re-enable:",
      "// export const BACKEND_ORIGIN = 'http://13.200.97.252';",
    ].join("\n"),
    "base_url: https origin");
  fs.writeFileSync(BASE, b);
  console.log("PATCH: backend origin is now https (was cleartext http)");

  // Guard: if any other cleartext URL is still pointing at the backend, fail the
  // build rather than shipping a half-migrated app.
  const after = readMust(BASE);
  const live = after
    .split("\n")
    .filter(l => l.indexOf("http://") !== -1 && !/^\s*\/\//.test(l));
  if (live.length) {
    throw new Error("PATCH: cleartext http:// still active in base_url.ts -> " + live.join(" | "));
  }
  console.log("PATCH: verified no active cleartext URL remains in base_url.ts");
}

// ---------------------------------------------------------------------------
// v32 - temporary early-adopter bypass of the "Access Required" gate
//
// Client decision (30 Sep): while the platform is still early, a new user who
// has verified their OTP goes straight to profile creation. The Access
// Required screen - which offered the premium pass and the invite code - is
// skipped entirely rather than having its buttons hidden, so there is no dead
// end left behind it and no half-working payment screen to stumble into.
//
// NOT touched: the invite-code popup that appears from the drawer after login
// or signup (src/navigation/drawer-navigation/drawercontent.tsx). That stays
// exactly as it is, as asked.
//
// To put the gate back later, change 'RegisterUserScreen' back to
// 'AccessRequiredScreen' in the two places below. The screen itself, its
// route registration and its code are all left untouched and still work.
// ---------------------------------------------------------------------------

{
  const OTP = "src/screen/account-creation/auth/otp-screen/index.tsx";
  let s = readMust(OTP);
  s = replaceOnce(s,
    [
      "        (navigation as any).navigate('AccessRequiredScreen', {",
      "          phone: phoneWithoutPlus,",
      "          otpToken,",
      "        });",
    ].join("\n"),
    [
      "        // TEMPORARY EARLY-ADOPTER BYPASS (client decision, 30 Sep).",
      "        // Was: navigate('AccessRequiredScreen', ...) - the invite code /",
      "        // premium pass gate. New users now go straight to profile setup.",
      "        // Restore by putting 'AccessRequiredScreen' back here.",
      "        (navigation as any).navigate('RegisterUserScreen', {",
      "          phone: phoneWithoutPlus,",
      "          otpToken,",
      "        });",
    ].join("\n"),
    "otp screen: skip the access gate");
  fs.writeFileSync(OTP, s);
  console.log("PATCH: OTP screen now goes straight to profile setup");
}

{
  // The second OTP screen in the project takes the same path. Bypass it too,
  // so the gate cannot be reached by whichever route is wired up.
  const V = "src/screen/account-creation/auth/verify-otp-screen/index.tsx";
  let v = readMust(V);
  v = replaceOnce(v,
    [
      "        (navigation as any).navigate('AccessRequiredScreen', {",
      "          phone: phone,",
      "          otpToken: otpToken,",
      "        });",
    ].join("\n"),
    [
      "        // TEMPORARY EARLY-ADOPTER BYPASS - see otp-screen/index.tsx.",
      "        (navigation as any).navigate('RegisterUserScreen', {",
      "          phone: phone,",
      "          otpToken: otpToken,",
      "        });",
    ].join("\n"),
    "verify-otp screen: skip the access gate");
  fs.writeFileSync(V, v);
  console.log("PATCH: second OTP screen bypasses the gate as well");
}

{
  // Safety net: prove no navigation to the gate survives anywhere in the app.
  const files = [];
  const walk = d => {
    for (const e of fs.readdirSync(d, {withFileTypes: true})) {
      const p = d + "/" + e.name;
      if (e.isDirectory()) walk(p);
      else if (/\.(ts|tsx|js|jsx)$/.test(e.name)) files.push(p);
    }
  };
  walk("src");
  const offenders = [];
  for (const f of files) {
    // Strip // comments first - the notes left above each change mention the
    // old screen name by design and must not count as a live route.
    const t = fs
      .readFileSync(f, "utf8")
      .split("\n")
      .filter(l => !/^\s*\/\//.test(l))
      .join("\n");
    // A navigate/reset that targets the gate. The route registration in the
    // navigator and the screen's own file are fine and expected.
    const re = /(navigate|reset)\s*\([\s\S]{0,80}['"]AccessRequiredScreen['"]/;
    if (re.test(t)) offenders.push(f);
  }
  if (offenders.length) {
    throw new Error("PATCH: a route to the access gate still exists -> " + offenders.join(", "));
  }
  console.log("PATCH: verified no screen navigates to the access gate any more");
}


