{const P="src/utils/e2ee/keyManager.ts";let t=readMust(P);t=replaceOnce(t,"/**\n * Ensure THIS device is registered for E2EE.","/**\n * Re-publish an identity this device ALREADY has.\n *\n * Used when the server has no record of us but we hold a local identity. The\n * identity key itself is reused -- regenerating it would invalidate any session\n * a peer has already built with us. The signed prekey has to be regenerated\n * because its signature is never persisted locally, only the key pair; a fresh\n * one signed by the same identity is exactly what prekey rotation does anyway.\n */\nasync function republishIdentity(\n  identityKeyPair: any,\n  deviceId: number,\n): Promise<void> {\n  const s = getStore();\n  let registrationId = await s.getLocalRegistrationId();\n  if (registrationId == null) {\n    registrationId = await KeyHelper.generateRegistrationId();\n    await s.saveLocalRegistrationId(registrationId);\n  }\n  const freshSigned = await KeyHelper.generateSignedPreKey(\n    identityKeyPair,\n    SIGNED_PREKEY_ID,\n  );\n  await s.storeSignedPreKey(SIGNED_PREKEY_ID, freshSigned.keyPair);\n  const oneTimePreKeys = await generateAndPublishOneTimePreKeys(\n    ONE_TIME_PREKEY_BATCH,\n  );\n  await publishSignalKeys({\n    deviceId,\n    registrationId,\n    identityKey: abToBase64(identityKeyPair.pubKey),\n    signedPreKey: {\n      keyId: SIGNED_PREKEY_ID,\n      publicKey: abToBase64(freshSigned.keyPair.pubKey),\n      signature: abToBase64(freshSigned.signature),\n    },\n    oneTimePreKeys,\n  });\n}\n\n/**\n * Ensure THIS device is registered for E2EE.","E2EE: can republish an identity the server never received");fs.writeFileSync(P,t);console.log("PATCH v36: "+"E2EE: can republish an identity the server never received");}
{const P="src/utils/e2ee/keyManager.ts";let t=readMust(P);t=replaceOnce(t,"  const existingIdentity = await s.getIdentityKeyPair();\n  if (existingIdentity) {\n    await replenishIfNeeded();\n    return false;\n  }","  const existingIdentity = await s.getIdentityKeyPair();\n  if (existingIdentity) {\n    // The identity is saved locally BEFORE it is published, so a publish that\n    // failed -- or a build that ran when the server had no key directory at\n    // all -- leaves this device looking registered here while the server has\n    // never heard of it. In that state no peer can open a session with us and\n    // every outgoing message fails, permanently, because this branch used to\n    // return without ever trying to publish again. So ask the server.\n    let serverKnowsUs = true;\n    try {\n      const { registered } = await getSignalKeyCount(deviceId);\n      serverKnowsUs = !!registered;\n    } catch (e) {\n      // A transient network failure is not evidence that we are unregistered;\n      // assume we are fine and re-check on the next call.\n      serverKnowsUs = true;\n    }\n    if (serverKnowsUs) {\n      await replenishIfNeeded();\n      return false;\n    }\n    await republishIdentity(existingIdentity, deviceId);\n    return true;\n  }","E2EE: a device the server does not know re-registers itself");fs.writeFileSync(P,t);console.log("PATCH v36: "+"E2EE: a device the server does not know re-registers itself");}
